  function fitGrid(){const grid=$('.grid'),n=S.tracks.length;if(!grid||!n||!grid.clientWidth||!grid.clientHeight)return;const dense=n>=9;grid.classList.toggle('dense',dense);const gap=dense?6:10,w=grid.clientWidth-20,h=grid.clientHeight-20,chrome=dense?64:87;let best={cols:1,rows:n,score:-1};const fixed=S.layout==='two'?2:S.layout==='four'?4:0;for(let cols=1;cols<=n;cols++){if(fixed&&cols!==Math.min(fixed,n))continue;const rows=Math.ceil(n/cols),cw=(w-(cols-1)*gap)/cols,ch=(h-(rows-1)*gap)/rows;const visible=Math.max(0,Math.min(cw/1.6,ch-chrome)),score=visible*visible*(1-(cols*rows-n)/(cols*rows)*.06);if(score>best.score)best={cols,rows,score};}grid.style.setProperty('--review-cols',best.cols);grid.style.setProperty('--review-rows',best.rows);grid.style.setProperty('--review-gap',gap+'px');grid.dataset.columns=best.cols;grid.dataset.rows=best.rows;}
