  async function buildMusicWaveform(t,file){if(file.size>40*1024*1024){t.waveformError='音频较大，可直接拖动时间条试听。';updateMusicUI(t);return;}try{const Decoder=globalThis.OfflineAudioContext||globalThis.webkitOfflineAudioContext;if(!Decoder)throw Error('no decoder');const context=new Decoder(1,1,44100),decoded=await context.decodeAudioData(await file.arrayBuffer());if(!current()||S.audio!==t)return;const bins=180,channels=Array.from({length:Math.min(2,decoded.numberOfChannels)},(_,i)=>decoded.getChannelData(i));t.waveform=Array.from({length:bins},(_,i)=>{const start=Math.floor(i*decoded.length/bins),end=Math.floor((i+1)*decoded.length/bins),step=Math.max(1,Math.floor((end-start)/1200));let peak=0;for(const channel of channels)for(let j=start;j<end;j+=step)peak=Math.max(peak,Math.abs(channel[j]));return peak;});t.waveformError='';updateMusicUI(t);}catch{if(current()&&S.audio===t){t.waveformError='波形暂不可用，可直接拖动时间条试听。';updateMusicUI(t);}}}
