  function updateMusicUI(t){if(!t||S.audio!==t)return;$('#audio').textContent='♫ 配乐 · 从 '+t.in.toFixed(2)+'s';const panel=$('.audio-panel');if(!$('#music-start-number'))return;const duration=t.duration||0,position=audioPreview?.currentTime||0;$('#music-preview-time').textContent=fmt(position)+' / '+fmt(duration);$('#music-preview-play').textContent=audioPreview&&!audioPreview.paused?'Ⅱ 暂停试听':'▶ 单独试听';$('#music-preview-seek').max=duration||1;if(root.activeElement!==$('#music-preview-seek'))$('#music-preview-seek').value=position;$('#music-start-number').max=Math.max(0,duration-.05);if(root.activeElement!==$('#music-start-number'))$('#music-start-number').value=t.in.toFixed(2);if(root.activeElement!==$('#music-offset-number'))$('#music-offset-number').value=t.offset.toFixed(2);$('#music-summary').textContent='联播到 '+t.offset.toFixed(2)+' 秒时，音乐从原曲 '+t.in.toFixed(2)+' 秒开始。';$('#music-wave-hint').textContent=t.error||t.waveformError||(t.waveform?'点击波形或拖动时间条找音乐起点。':'正在读取波形；也可直接拖动时间条。');for(const button of panel.querySelectorAll('[data-music-ready]'))button.disabled=!t.ready;drawMusicWave(t);}
